// ABOUTME: The deployment's runtime settings, read from the external /config.js a container writes at
// ABOUTME: start, so one built image serves any customer; each value falls back to the build-time env.

/**
 * What a deployment may set at run time.
 *
 * The bundle is the same for every customer, so anything that differs between installs is read here
 * instead of being baked in. The file is generated by the container entrypoint and must stay small:
 * a value that never differs between installs belongs in the build, not in this file.
 */
export interface RuntimeConfig {
  /** Which first-run paths the image offers: a demo kiosk, a production install, or both. */
  readonly deploymentMode?: 'demo' | 'production' | 'both';
  /** Allow a temporary database when OPFS is unavailable (a public demo). Never for production. */
  readonly allowTemporaryDatabase?: boolean;
  /** The error-reporting DSN; an empty string disables reporting. */
  readonly bugsinkDsn?: string;
  /** The version the deployment names itself, shown in diagnostics. */
  readonly appVersion?: string;
}

declare global {
  interface Window {
    readonly __SCHOOLPILOT_CONFIG__?: unknown;
  }
}

const text = (value: unknown): string | undefined =>
  typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;

const flag = (value: unknown): boolean | undefined => {
  if (typeof value === 'boolean') return value;
  if (value === 'true') return true;
  if (value === 'false') return false;
  return undefined;
};

/**
 * The settings `/config.js` published, validated one value at a time.
 *
 * A malformed value falls back to the build-time setting rather than failing the boot: a typo in a
 * deployment's environment must not make the app unusable, and the fallback is the value the bundle
 * was built with.
 */
function readPublished(): RuntimeConfig {
  if (typeof window === 'undefined') return {};
  const published = window.__SCHOOLPILOT_CONFIG__;
  if (!published || typeof published !== 'object') return {};
  const source = published as Record<string, unknown>;
  const deploymentMode = text(source.deploymentMode);
  return {
    ...(deploymentMode === 'demo' || deploymentMode === 'production' || deploymentMode === 'both'
      ? { deploymentMode }
      : {}),
    ...(flag(source.allowTemporaryDatabase) === undefined
      ? {}
      : { allowTemporaryDatabase: flag(source.allowTemporaryDatabase) }),
    ...(text(source.bugsinkDsn) === undefined ? {} : { bugsinkDsn: text(source.bugsinkDsn) }),
    ...(text(source.appVersion) === undefined ? {} : { appVersion: text(source.appVersion) }),
  };
}

/** The runtime settings of this page. */
export function runtimeConfig(): RuntimeConfig {
  return readPublished();
}

/** The deployment mode the image enforces, or undefined when it offers both. */
export function runtimeDeploymentMode(): RuntimeConfig['deploymentMode'] | undefined {
  return runtimeConfig().deploymentMode;
}

/** True when the deployment allows a throwaway in-memory database (a public demo). */
export function runtimeAllowsTemporaryDatabase(): boolean | undefined {
  return runtimeConfig().allowTemporaryDatabase;
}

/** The error-reporting DSN: the runtime setting, else the build-time one. */
export function runtimeBugsinkDsn(built: string | undefined): string | undefined {
  return runtimeConfig().bugsinkDsn ?? built;
}

/** The version the deployment names: the runtime setting, else the build-time one. */
export function runtimeAppVersion(built: string | undefined): string {
  return runtimeConfig().appVersion ?? text(built) ?? '1.0.0';
}
